import{d as l,C as e,o as h,c as u,a3 as i,E as t,j as a,a as m}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·子路","description":"《论语》第 13 篇「子路」——三十章原文与导读。先之劳之、必也正名、其身正不令而行、近者说远者来、欲速则不达、和而不同。","frontmatter":{"title":"论语·子路","description":"《论语》第 13 篇「子路」——三十章原文与导读。先之劳之、必也正名、其身正不令而行、近者说远者来、欲速则不达、和而不同。","category":"guide","aliases":["子路","子路篇","子路第十三","论语子路","lunyu 子路"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-13.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-13.md","lastUpdated":1790316338000}'),y={name:"lizhimingde/sishu-wujing/lunyu/chapter-13.md"},x=l({...y,setup(d){const s=[{id:"yi",label:"一、先之，劳之",showLabel:!0,sentences:[["子路问政，子曰：“",{text:"先之",glossary:"xianzhi"},"，",{text:"劳之",glossary:"laozhi"},"。”请益，曰：“",{text:"无倦",glossary:"wujuan"},"。”"]],note:"子路问政。孔子说：「先之，劳之」——自己带头去做，然后使百姓勤劳。请再说些，答：「无倦」——不要懈怠。"},{id:"er",label:"二、先有司，赦小过，举贤才",showLabel:!0,sentences:[["仲弓为季氏宰，问政，子曰：“",{text:"先有司",glossary:"xianyousi"},"，",{text:"赦小过",glossary:"shexiaoguo"},"，举贤才。”曰：“焉知贤才而举之？”曰：“举尔所知。尔所不知，人其舍诸？”"]],note:"仲弓为季氏之宰，问政。孔子说：「先有司，赦小过，举贤才」——先让各职司各负其责，宽赦小的过失，举用贤才。问「焉知贤才而举之」，答：「举尔所知。尔所不知，人其舍诸」——举用你所知道的；你所不知道的，别人难道会舍弃他们吗？"},{id:"san",label:"三、必也正名乎",showLabel:!0,sentences:[["子路曰：“卫君待子而为政，子将奚先？”子曰：“必也",{text:"正名",glossary:"zhengming"},"乎！”子路曰：“有是哉，子之迂也！奚其正？”子曰：“野哉由也！君子于其所不知，盖",{text:"阙如",glossary:"queru"},"也。名不正，则言不顺；言不顺，则事不成；事不成，则礼乐不兴；礼乐不兴，则刑罚不",{text:"中",glossary:"zhong-dang"},"；刑罚不中，则民无所",{text:"措手足",glossary:"cuoshouzu"},"。故君子名之必可言也，言之必可行也。君子于其言，无所",{text:"苟",glossary:"gou"},"而已矣。”"]],note:"子路说：「卫君待子而为政，子将奚先」——卫国国君等着您去为政，您先做什么？孔子说：「必也正名乎」——一定先正名分！子路说：「有是哉，子之迂也！奚其正」——竟有这样的事，您太迂阔了！何必正名？孔子说：「野哉由也」——仲由真粗野啊！「君子于其所不知，盖阙如也」——君子对所不知的，总存疑不言。「名不正，则言不顺；言不顺，则事不成；事不成，则礼乐不兴；礼乐不兴，则刑罚不中；刑罚不中，则民无所措手足」——名不正则言不顺，言不顺则事不成，事不成则礼乐不兴，礼乐不兴则刑罚失当，刑罚失当则百姓手足无措。见「正名」之重。"},{id:"si",label:"四、焉用稼",showLabel:!0,sentences:[["樊迟请学",{text:"稼",glossary:"jia"},"，子曰：“吾不如老农。”请学为",{text:"圃",glossary:"pu"},"，曰：“吾不如老圃。”樊迟出，子曰：“小人哉樊须也！上好礼，则民莫敢不敬；上好义，则民莫敢不服；上好信，则民莫敢不用情。夫如是，则四方之民",{text:"襁负",glossary:"qiangfu"},"其子而至矣，焉用稼？”"]],note:"樊迟请学稼。孔子说：「吾不如老农」。请学为圃，答：「吾不如老圃」。樊迟出，孔子说：「小人哉樊须也」——樊须真是小人啊！「上好礼，则民莫敢不敬；上好义，则民莫敢不服；上好信，则民莫敢不用情」——在上者好礼，民莫敢不敬；好义，民莫敢不服；好信，民莫敢不用真情。「夫如是，则四方之民襁负其子而至矣，焉用稼」——如此则四方之民背子来投，哪里用得着自己种庄稼？"},{id:"wu",label:"五、诵《诗》三百",showLabel:!0,sentences:[["子曰：“诵《诗》三百，授之以政，不达；使于四方，不能",{text:"专对",glossary:"zhuandui"},"；虽多，亦奚以为？”"]],note:"「诵《诗》三百，授之以政，不达；使于四方，不能专对；虽多，亦奚以为」——能诵《诗》三百篇，授以政事却办不通，出使四方却不能专对应答；诗虽多，又有何用？"},{id:"liu",label:"六、其身正，不令而行",showLabel:!0,sentences:[["子曰：“其身正，不令而行；其身不正，虽令不从。”"]],note:"「其身正，不令而行；其身不正，虽令不从」——自身端正，不下令事也行得通；自身不端正，纵然下令也无人听从。"},{id:"qi",label:"七、鲁卫之政，兄弟也",showLabel:!0,sentences:[["子曰：“鲁卫之政，兄弟也。”"]],note:"「鲁卫之政，兄弟也」——鲁国与卫国的政事，如兄弟一般（同出周公之后，政亦相似）。"},{id:"ba",label:"八、善居室",showLabel:!0,sentences:[["子谓卫公子荆，“",{text:"善居室",glossary:"shanjushi"},"。始有，曰：‘苟合矣。’少有，曰：‘苟完矣。’富有，曰：‘苟美矣。’”"]],note:"孔子评卫国公子荆「善居室」——善于持家。其言曰：「始有，曰『苟合矣』」（刚有一点，便说差不多够了）；「少有，曰『苟完矣』」（稍多些，便说差不多完备了）；「富有，曰『苟美矣』」（富足了，便说差不多完美了）。写其知足而不侈。"},{id:"jiu",label:"九、庶矣哉",showLabel:!0,sentences:[["子适卫，冉有仆，子曰：“",{text:"庶矣哉",glossary:"shuyizai"},"！”冉有曰：“既庶矣，又何加焉？”曰：“富之。”曰：“既富矣，又何加焉？”曰：“教之。”"]],note:"孔子到卫国去，冉有为之驾车。孔子说：「庶矣哉」——人口真多啊！冉有问：「既庶矣，又何加焉」——既已人口众多，还要做什么？答：「富之」——使之富裕。又问：「既富矣，又何加焉」？答：「教之」——教化他们。庶→富→教，为孔子的治理次第。"},{id:"shi",label:"十、期月而已可也",showLabel:!0,sentences:[["子曰：“苟有用我者，",{text:"期月",glossary:"qiyue"},"而已可也，三年有成。”"]],note:"「苟有用我者，期月而已可也，三年有成」——若有人用我，一年（期月＝满一月，此指一周年）便可见效，三年便有成就。"},{id:"shiyi",label:"十一、胜残去杀",showLabel:!0,sentences:[["子曰：“‘善人为邦百年，亦可以",{text:"胜残去杀",glossary:"shengcanqusha"},"矣。’诚哉是言也！”"]],note:"「『善人为邦百年，亦可以胜残去杀矣』，诚哉是言也」——「善人治国百年，也可以化去残暴、免除刑杀了」，这话真对啊！"},{id:"shier",label:"十二、必世而后仁",showLabel:!0,sentences:[["子曰：“如有王者，必",{text:"世",glossary:"shi-dai"},"而后仁。”"]],note:"「如有王者，必世而后仁」——若有王者兴起，也须三十年（世＝三十年）而后仁政可成。言仁政之难。"},{id:"shisan",label:"十三、不能正其身，如正人何",showLabel:!0,sentences:[["子曰：“苟正其身矣，于从政乎何有？不能正其身，如正人何？”"]],note:"「苟正其身矣，于从政乎何有？不能正其身，如正人何」——若能端正自身，从政有何难？不能端正自身，又怎能正人？"},{id:"shisi",label:"十四、何晏也",showLabel:!0,sentences:[["冉子退朝，子曰：“何",{text:"晏",glossary:"yan-wan"},"也？”对曰：“有政。”子曰：“其事也。如有政，虽不吾以，吾其与闻之。”"]],note:"冉有退朝而回，孔子说：「何晏也」——为何回来这样晚？冉有答：「有政」——有政事。孔子说：「其事也。如有政，虽不吾以，吾其与闻之」——那是事务吧；若真有政事，纵不用我，我也会听说的。"},{id:"shiwu",label:"十五、一言而可以兴邦",showLabel:!0,sentences:[["定公问：“一言而可以兴邦，有诸？”孔子对曰：“言不可以若是，其",{text:"几",glossary:"ji-jin"},"也。人之言曰：‘为君难，为臣不易。’如知为君之难也，不几乎一言而兴邦乎？”曰：“一言而丧邦，有诸？”孔子对曰：“言不可以若是其几也。人之言曰：‘予无乐乎为君，唯其言而莫予违也。’如其善而莫之违也，不亦善乎？如不善而莫之违也，不几乎一言而丧邦乎？”"]],note:"定公问：「一言而可以兴邦，有诸」——一句话便可兴邦，有这事吗？孔子答：话不能这样说，但近乎此者自有。「人之言曰：为君难，为臣不易」，若真知为君之难，「不几乎一言而兴邦乎」——不就近乎一言兴邦了吗？又问「一言而丧邦」，答：「予无乐乎为君，唯其言而莫予违也」（我为君无甚乐趣，只是我的话无人敢违）；若所言不善而无人违之，「不几乎一言而丧邦乎」——不就近乎一言丧邦了吗？"},{id:"shiliu",label:"十六、近者说，远者来",showLabel:!0,sentences:[["叶公问政，子曰：“近者说，远者来。”"]],note:"叶公问政。孔子说：「近者说（悦），远者来」——近处的人欢悦，远方的人来归。"},{id:"shiqi",label:"十七、欲速则不达",showLabel:!0,sentences:[["子夏为",{text:"莒父",glossary:"jufu"},"宰，问政，子曰：“无欲速，无见小利。",{text:"欲速则不达",glossary:"yusuzebuda"},"，见小利则大事不成。”"]],note:"子夏为莒父之宰，问政。孔子说：「无欲速，无见小利。欲速则不达，见小利则大事不成」——不要急于求成，不要贪图小利；欲速则不达，见小利则大事不成。"},{id:"shiba",label:"十八、父为子隐，子为父隐",showLabel:!0,sentences:[["叶公语孔子曰：“吾党有",{text:"直躬",glossary:"zhigong"},"者，其父",{text:"攘羊",glossary:"rangyang"},"，而子",{text:"证",glossary:"zheng-zheng"},"之。”孔子曰：“吾党之直者异于是。父为子隐，子为父隐，直在其中矣。”"]],note:"叶公对孔子说：「吾党有直躬者，其父攘羊，而子证之」——我乡里有个名叫直躬的正直人，其父偷羊，他出来作证。孔子说：「吾党之直者异于是：父为子隐，子为父隐，直在其中矣」——我乡里的正直与此不同：父为子隐，子为父隐，直就在其中了。（此章于「正直」之义争议甚多。）"},{id:"shijiu",label:"十九、居处恭，执事敬，与人忠",showLabel:!0,sentences:[["樊迟问仁，子曰：“居处恭，执事敬，与人忠。虽之夷狄，不可弃也。”"]],note:"樊迟问仁。孔子说：「居处恭，执事敬，与人忠。虽之夷狄，不可弃也」——平居恭敬，行事认真，待人忠诚；纵然到夷狄之地，也不可舍弃。"},{id:"ershi",label:"二十、行己有耻",showLabel:!0,sentences:[["子贡问曰：“何如斯可谓之士矣？”子曰：“行己有耻，使于四方不辱君命，可谓士矣。”曰：“敢问其次。”曰：“宗族称孝焉，乡党称弟焉。”曰：“敢问其次。”曰：“言必信，行必果，",{text:"硁硁然",glossary:"kengkengran"},"小人哉！抑亦可以为次矣。”曰：“今之从政者何如？”子曰：“噫！",{text:"斗筲",glossary:"doushao"},"之人，何足算也！”"]],note:"子贡问：「何如斯可谓之士矣」——怎样可称为士？孔子说：「行己有耻，使于四方不辱君命，可谓士矣」——自己行事有羞耻之心，出使四方不辱君命，可称为士。问其次，答：「宗族称孝焉，乡党称弟（悌）焉」——宗族称其孝，乡党称其悌。再问其次，答：「言必信，行必果，硁硁然小人哉！抑亦可以为次矣」——言必信、行必果，这是固执的小人（硁硁＝固执貌）！但也可算再次一等。"},{id:"ershiyi",label:"二十一、不得中行而与之",showLabel:!0,sentences:[["子曰：“不得",{text:"中行",glossary:"zhongxing"},"而与之，必也",{text:"狂狷",glossary:"kuangjuan"},"乎！狂者进取，狷者有所不为也。”"]],note:"「不得中行而与之，必也狂狷乎」——找不到行中道者与之相交，那只有取狂者与狷者了吧！「狂者进取，狷者有所不为也」——狂者勇于进取，狷者有所不为（洁身自好）。"},{id:"ershier",label:"二十二、不恒其德，或承之羞",showLabel:!0,sentences:[["子曰：“南人有言曰：‘人而无",{text:"恒",glossary:"heng"},"，不可以作巫医。’善夫！”“不恒其德，或承之羞。”子曰：“不占而已矣。”"]],note:"孔子说：「南人有言曰：人而无恒，不可以作巫医」——南方人有言：人若无恒心，连巫医也做不成。说得真好啊！又引《易》「不恒其德，或承之羞」（不能恒守其德，或招致羞辱）。孔子说：「不占而已矣」——不必占卜（便知其结果）了。"},{id:"ershisan",label:"二十三、君子和而不同",showLabel:!0,sentences:[["子曰：“君子和而不同，小人同而不和。”"]],note:"「君子和而不同，小人同而不和」——君子和谐而不盲从苟同，小人盲从苟同而不和谐。"},{id:"ershisi",label:"二十四、乡人皆好之",showLabel:!0,sentences:[["子贡问曰：“乡人皆好之，何如？”子曰：“未可也。”“乡人皆恶之，何如？”子曰：“未可也。不如乡人之善者好之，其不善者恶之。”"]],note:"子贡问：「乡人皆好之，何如」——全乡人都喜欢他，如何？孔子说：「未可也」。「乡人皆恶之，何如」？答：「未可也。不如乡人之善者好之，其不善者恶之」——还不如使全乡的好人喜欢他、坏人厌恶他。"},{id:"ershiwu",label:"二十五、易事而难说",showLabel:!0,sentences:[["子曰：“君子易事而难说也，说之不以道不说也，及其使人也",{text:"器之",glossary:"qizhi"},"；小人难事而易说也，说之虽不以道说也，及其使人也",{text:"求备",glossary:"qiubei"},"焉。”"]],note:"「君子易事而难说（悦）也，说之不以道不说也，及其使人也器之」——君子容易共事而难以取悦：不以正道取悦则他不悦；及其用人，则量才而任（器＝量才）。「小人难事而易说也，说之虽不以道说也，及其使人也求备焉」——小人难以共事而容易取悦：纵不以正道取悦他也高兴；及其用人，却求全责备。"},{id:"ershiliu",label:"二十六、君子泰而不骄",showLabel:!0,sentences:[["子曰：“君子",{text:"泰",glossary:"tai-shu"},"而不骄，小人骄而不泰。”"]],note:"「君子泰而不骄，小人骄而不泰」——君子安详舒泰而不傲慢，小人傲慢而不安详。"},{id:"ershiqi",label:"二十七、刚、毅、木、讷近仁",showLabel:!0,sentences:[["子曰：“刚、毅、木、",{text:"讷",glossary:"ne-shen"},"近仁。”"]],note:"「刚、毅、木、讷近仁」——刚强、果毅、质朴、慎言，皆近于仁。"},{id:"ershiba",label:"二十八、切切偲偲，怡怡如也",showLabel:!0,sentences:[["子路问曰：“何如斯可谓之士矣？”子曰：“",{text:"切切偲偲",glossary:"qieqiesisi"},"，",{text:"怡怡如",glossary:"yiyiru"},"也，可谓士矣。朋友切切偲偲，兄弟怡怡。”"]],note:"子路问：「何如斯可谓之士矣」？孔子说：「切切偲偲，怡怡如也，可谓士矣」——互相恳切督责（切切偲偲＝互相勉励责善），又和悦相处，可称为士。「朋友切切偲偲，兄弟怡怡」——朋友之间互相督责，兄弟之间和悦相处。"},{id:"ershijiu",label:"二十九、善人教民七年",showLabel:!0,sentences:[["子曰：“善人教民七年，亦可以",{text:"即戎",glossary:"jirong"},"矣。”"]],note:"「善人教民七年，亦可以即戎矣」——善人教化百姓七年，也可以让他们作战了（即戎＝从军）。"},{id:"sanshi",label:"三十、以不教民战，是谓弃之",showLabel:!0,sentences:[["子曰：“以不教民战，是谓弃之。”"]],note:"「以不教民战，是谓弃之」——用未经训练的百姓去作战，这叫做抛弃他们。全篇以此收束。"}],r=[{id:"xianzhi",term:"先之",pinyin:"xiān zhī",meaning:"自己先做在前头（以身作则）。之：指百姓。"},{id:"laozhi",term:"劳之",pinyin:"láo zhī",meaning:"使百姓勤劳地工作。一说「劳」为慰劳——先以身先，再慰劳其劳。"},{id:"wujuan",term:"无倦",pinyin:"wú juàn",meaning:"不懈怠。子路请益，孔子只给这两个字——把已说的做到底。"},{id:"xianyousi",term:"先有司",pinyin:"xiān yǒu sī",meaning:"先让具体职事的官吏各负其责。有司：专管某事的官吏。"},{id:"shexiaoguo",term:"赦小过",pinyin:"shè xiǎo guò",meaning:"宽赦小的过失。用人看大节，不苛责细故。"},{id:"zhengming",term:"正名",pinyin:"zhèng míng",meaning:"辨正名分，使名实相符。此章为《论语》论「名」最集中的一段。"},{id:"queru",term:"阙如",pinyin:"quē rú",meaning:"空缺着、暂付阙如。阙：同「缺」。于其所不知，盖阙如也：不懂的就存疑不说。"},{id:"zhong-dang",term:"中",pinyin:"zhòng",meaning:"得当、恰当。刑罚不中：刑罚不得当。"},{id:"cuoshouzu",term:"措手足",pinyin:"cuò shǒu zú",meaning:"安放手脚，指有所依循。无所措手足：不知该怎么办才好。"},{id:"gou",term:"苟",pinyin:"gǒu",meaning:"苟且、马虎。无所苟而已矣：一点也马虎不得。"},{id:"jia",term:"稼",pinyin:"jià",meaning:"种庄稼。"},{id:"pu",term:"圃",pinyin:"pǔ",meaning:"菜园、种菜。"},{id:"qiangfu",term:"襁负",pinyin:"qiǎng fù",meaning:"用襁褓背着孩子。襁：背婴儿的布带。状百姓归附之众。"},{id:"zhuandui",term:"专对",pinyin:"zhuān duì",meaning:"独立应对（使臣出使时随机应答，不辱使命）。"},{id:"shanjushi",term:"善居室",pinyin:"shàn jū shì",meaning:"善于持家、治家。此处指他安于渐次改善、不贪求。"},{id:"shuyizai",term:"庶矣哉",pinyin:"shù yǐ zāi",meaning:"人真多啊！庶：众多。"},{id:"qiyue",term:"期月",pinyin:"jī yuè",meaning:"满一月（一说满一年）。喻时间不长。"},{id:"shengcanqusha",term:"胜残去杀",pinyin:"shèng cán qù shā",meaning:"使残暴的人改化，因而可以不用死刑。胜：化服。"},{id:"shi-dai",term:"世",pinyin:"shì",meaning:"三十年为一世。「必世而后仁」：须三十年才能使仁道成就。"},{id:"yan-wan",term:"晏",pinyin:"yàn",meaning:"晚、迟。何晏也：怎么回来这样晚？"},{id:"ji-jin",term:"几",pinyin:"jī",meaning:"近、接近。其几也：话不能说得这样机械，该近于这个道理。"},{id:"jufu",term:"莒父",pinyin:"jǔ fǔ",meaning:"鲁国邑名。"},{id:"yusuzebuda",term:"欲速则不达",pinyin:"yù sù zé bù dá",meaning:"急于求成就达不到目的。"},{id:"zhigong",term:"直躬",pinyin:"zhí gōng",meaning:"「直躬」为人名（一说「直身而行」）。此章是《论语》中论亲情与法理冲突最有名的一段。"},{id:"rangyang",term:"攘羊",pinyin:"rǎng yáng",meaning:"偷羊。攘：窃取。"},{id:"zheng-zheng",term:"证",pinyin:"zhèng",meaning:"告发、作证。"},{id:"kengkengran",term:"硁硁然",pinyin:"kēng kēng rán",meaning:"浅陋固执的样子。言必信、行必果而不问是否合义，是固执的小器。"},{id:"doushao",term:"斗筲",pinyin:"dǒu shāo",meaning:"斗与筲都是小容器，喻器量狭小、才识短浅的人。"},{id:"zhongxing",term:"中行",pinyin:"zhōng xíng",meaning:"中道而行、无过不及的人（即「中行」之士）。"},{id:"kuangjuan",term:"狂狷",pinyin:"kuáng juàn",meaning:"狂：激进进取；狷：孤洁自守、有所不为。虽不及中行，但可与之。"},{id:"heng",term:"恒",pinyin:"héng",meaning:"恒心、恒常。人而无恒：人若没有恒心。"},{id:"qizhi",term:"器之",pinyin:"qì zhī",meaning:"量才而用（如器有其用）。"},{id:"qiubei",term:"求备",pinyin:"qiú bèi",meaning:"求全责备。"},{id:"tai-shu",term:"泰",pinyin:"tài",meaning:"舒泰、从容大方（与「骄」相对）。"},{id:"ne-shen",term:"讷",pinyin:"nè",meaning:"言语迟钝，指说话谨慎不多。"},{id:"qieqiesisi",term:"切切偲偲",pinyin:"qiè qiè sī sī",meaning:"互相切磋、督责勉励的样子（朋友之间）。"},{id:"yiyiru",term:"怡怡如",pinyin:"yí yí rú",meaning:"和顺愉快的样子（兄弟之间）。"},{id:"jirong",term:"即戎",pinyin:"jí róng",meaning:"从事作战、上战场。戎：兵事。"}];return(p,n)=>{const o=e("DaoTextReading"),g=e("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=i("",6)),t(o,{colophon:"子路第十三 · 三十章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·子路 原文"}),n[1]||(n[1]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[m("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(g,{items:[{term:"先之",pinyin:["xiān","zhī"],meaning:"自己先做在前头（以身作则）。之：指百姓。"},{term:"劳之",pinyin:["láo","zhī"],meaning:"使百姓勤劳地工作。一说「劳」为慰劳——先以身先，再慰劳其劳。"},{term:"无倦",pinyin:["wú","juàn"],meaning:"不懈怠。子路请益，孔子只给这两个字——把已说的做到底。"},{term:"先有司",pinyin:["xiān","yǒu","sī"],meaning:"先让具体职事的官吏各负其责。有司：专管某事的官吏。"},{term:"赦小过",pinyin:["shè","xiǎo","guò"],meaning:"宽赦小的过失。用人看大节，不苛责细故。"},{term:"正名",pinyin:["zhèng","míng"],meaning:"辨正名分，使名实相符。此章为《论语》论「名」最集中的一段。"},{term:"阙如",pinyin:["quē","rú"],meaning:"空缺着、暂付阙如。阙：同「缺」。于其所不知，盖阙如也：不懂的就存疑不说。"},{term:"中",pinyin:["zhòng"],meaning:"得当、恰当。刑罚不中：刑罚不得当。"},{term:"措手足",pinyin:["cuò","shǒu","zú"],meaning:"安放手脚，指有所依循。无所措手足：不知该怎么办才好。"},{term:"苟",pinyin:["gǒu"],meaning:"苟且、马虎。无所苟而已矣：一点也马虎不得。"},{term:"稼",pinyin:["jià"],meaning:"种庄稼。"},{term:"圃",pinyin:["pǔ"],meaning:"菜园、种菜。"},{term:"襁负",pinyin:["qiǎng","fù"],meaning:"用襁褓背着孩子。襁：背婴儿的布带。状百姓归附之众。"},{term:"专对",pinyin:["zhuān","duì"],meaning:"独立应对（使臣出使时随机应答，不辱使命）。"},{term:"善居室",pinyin:["shàn","jū","shì"],meaning:"善于持家、治家。此处指他安于渐次改善、不贪求。"},{term:"庶矣哉",pinyin:["shù","yǐ","zāi"],meaning:"人真多啊！庶：众多。"},{term:"期月",pinyin:["jī","yuè"],meaning:"满一月（一说满一年）。喻时间不长。"},{term:"胜残去杀",pinyin:["shèng","cán","qù","shā"],meaning:"使残暴的人改化，因而可以不用死刑。胜：化服。"},{term:"世",pinyin:["shì"],meaning:"三十年为一世。「必世而后仁」：须三十年才能使仁道成就。"},{term:"晏",pinyin:["yàn"],meaning:"晚、迟。何晏也：怎么回来这样晚？"},{term:"几",pinyin:["jī"],meaning:"近、接近。其几也：话不能说得这样机械，该近于这个道理。"},{term:"莒父",pinyin:["jǔ","fǔ"],meaning:"鲁国邑名。"},{term:"欲速则不达",pinyin:["yù","sù","zé","bù","dá"],meaning:"急于求成就达不到目的。"},{term:"直躬",pinyin:["zhí","gōng"],meaning:"「直躬」为人名（一说「直身而行」）。此章是《论语》中论亲情与法理冲突最有名的一段。"},{term:"攘羊",pinyin:["rǎng","yáng"],meaning:"偷羊。攘：窃取。"},{term:"证",pinyin:["zhèng"],meaning:"告发、作证。"},{term:"硁硁然",pinyin:["kēng","kēng","rán"],meaning:"浅陋固执的样子。言必信、行必果而不问是否合义，是固执的小器。"},{term:"斗筲",pinyin:["dǒu","shāo"],meaning:"斗与筲都是小容器，喻器量狭小、才识短浅的人。"},{term:"中行",pinyin:["zhōng","xíng"],meaning:"中道而行、无过不及的人（即「中行」之士）。"},{term:"狂狷",pinyin:["kuáng","juàn"],meaning:"狂：激进进取；狷：孤洁自守、有所不为。虽不及中行，但可与之。"},{term:"恒",pinyin:["héng"],meaning:"恒心、恒常。人而无恒：人若没有恒心。"},{term:"器之",pinyin:["qì","zhī"],meaning:"量才而用（如器有其用）。"},{term:"求备",pinyin:["qiú","bèi"],meaning:"求全责备。"},{term:"泰",pinyin:["tài"],meaning:"舒泰、从容大方（与「骄」相对）。"},{term:"讷",pinyin:["nè"],meaning:"言语迟钝，指说话谨慎不多。"},{term:"切切偲偲",pinyin:["qiè","qiè","sī","sī"],meaning:"互相切磋、督责勉励的样子（朋友之间）。"},{term:"怡怡如",pinyin:["yí","yí","rú"],meaning:"和顺愉快的样子（兄弟之间）。"},{term:"即戎",pinyin:["jí","róng"],meaning:"从事作战、上战场。戎：兵事。"}]}),n[2]||(n[2]=i("",22))])}}});export{c as __pageData,x as default};
